  "claims": [
    {
      "claim": "L6 afatinib, the closest structural analog, shows low mouse liver microsomal intrinsic clearance (CLint 9.4 µL/min/mg), indicating no strong hepatic metabolic liability for this chemotype.",
      "card_ids": ["C260"]
    },
    {
      "claim": "L6 vandetanib shows low HLM intrinsic clearance (11.0 µL/min/mg) and a long metabolic half-life (~63 min), supporting slow hepatic elimination in the 4-anilinoquinazoline class.",
      "card_ids": ["C238", "C235"]
    },
    {
      "claim": "L6 lapatinib and tandutinib show low-to-moderate HLM CLint (16.7-22.8 and 22.03 µL/min/mg; tandutinib medium extraction); moderate hepatic clearance alone does not establish F < 20%.",
      "card_ids": ["C244", "C259", "C249"]
    },
    {
      "claim": "L3 afatinib oral exposure records show measurable systemic exposure after oral dosing (AUC0-24 459 ng·h/mL at 50 mg; steady-state Cmax 77 ng/mL at 50 mg; exposure at 20 mg), supporting F >= 20%.",
      "card_ids": ["C85", "C91", "C102", "C96", "C111"]
    },
    {
      "claim": "L4 Caco-2 records for the 4-anilinoquinazoline chemotype show high permeability (gefitinib Papp 8.37-10.41 x10^-6 cm/s, BCS II; vandetanib, erlotinib, icotinib high permeability), supporting adequate absorption.",
      "card_ids": ["C133", "C135", "C147"]
    },
    {
      "claim": "L5 C228 shows gefitinib oral availability is not impacted by Abcb1a/1b or Abcg2 knockout; efflux mechanism alone is not affirmative low-F evidence.",
      "card_ids": ["C228"]
    },
    {
      "claim": "L2 animal F records for lipophilic basic-amine kinase-inhibitor-like chemotypes show F >= 20% (toceranib 76.9% in dogs; compound 17p 27-100% across species).",
      "card_ids": ["C54", "C72"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C260", "C238", "C235", "C244", "C259", "C249", "C246", "C240", "C262", "C254"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule.",
    "No query-specific hepatic clearance or metabolic stability data; L6 records are for close analogs.",
    "Afatinib CLint is mouse-only; human hepatic clearance for the query is not measured.",
    "No matched oral-versus-IV exposure data for the query or afatinib/gefitinib.",
    "Aqueous solubility of the query is not measured.",
    "The query alpha,beta-unsaturated amide is a potential metabolic soft spot, but no experimental evidence quantifies its impact."
  ],
  "decision_summary": "L6 hepatic clearance records show the closest analog afatinib has low mouse liver microsomal CLint (9.4 µL/min/mg) and vandetanib has low HLM CLint (11.0 µL/min/mg, t1/2 ~63 min); lapatinib and tandutinib are low-to-moderate (16.7-22.8 and 22.03 µL/min/mg). No L6 record affirmatively supports F < 20%. Combined with L3 afatinib oral exposure, L4 high permeability, L5 efflux no-impact finding, and L2 animal F >= 20% records, the high prediction is maintained with moderate confidence."
}

